    # Extensions
    extensions = struct.pack('!H', len(ticket_ext) + len(early_data_ext))
    extensions += ticket_ext + early_data_ext
    
    # ClientHello body
    client_hello = struct.pack('!BB', TLS_1_3_VERSION[0], TLS_1_3_VERSION[1])
    client_hello += os.urandom(32)  # Random
    client_hello += struct.pack('!B', len(session_ticket))  # Session ID length
    client_hello += session_ticket  # Session ID
    client_hello += struct.pack('!H', 1)  # Cipher suites length
    client_hello += struct.pack('!H', 0x1301)  # TLS_AES_128_GCM_SHA256
    client_hello += struct.pack('!B', 0)  # Compression methods
    client_hello += extensions
    
    # Handshake message
    handshake = struct.pack('!BBH', HANDSHAKE_TYPE_CLIENT_HELLO, 0, len(client_hello))
    handshake += client_hello
    
    return handshake

